import sys

class Node:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def build_linked_list(values):
    if not values:
        return None
    head = Node(values[0])
    current = head
    for val in values[1:]:
        current.next = Node(val)
        current = current.next
    return head

def get_min_max(head):
    if not head:
        return 0, 0
    min_val = head.val
    max_val = head.val
    current = head
    while current:
        if current.val < min_val:
            min_val = current.val
        if current.val > max_val:
            max_val = current.val
        current = current.next
    return min_val, max_val

def bucket_sort(head):
    if not head or not head.next:
        return head

    min_val, max_val = get_min_max(head)

    if min_val == max_val:
        return head

    bucket_range = max_val - min_val + 1
    num_buckets = 100
    bucket_size = (bucket_range + num_buckets - 1) // num_buckets

    buckets = [[] for _ in range(num_buckets)]

    current = head
    while current:
        next_node = current.next
        current.next = None

        normalized_val = current.val - min_val
        bucket_idx = normalized_val // bucket_size
        if bucket_idx >= num_buckets:
            bucket_idx = num_buckets - 1

        buckets[bucket_idx].append(current)
        current = next_node

    for i in range(num_buckets):
        buckets[i].sort(key=lambda node: node.val)

    dummy = Node(0)
    tail = dummy

    for i in range(num_buckets):
        for node in buckets[i]:
            tail.next = node
            tail = tail.next

    return dummy.next

def print_linked_list(head):
    result = []
    current = head
    while current:
        result.append(str(current.val))
        current = current.next
    print(' '.join(result))

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    if n == 0:
        print()
        return

    values = list(map(int, data[1:n+1]))
    head = build_linked_list(values)
    sorted_head = bucket_sort(head)
    print_linked_list(sorted_head)

if __name__ == "__main__":
    main()
